"""Exact automorphism quotient of fixed core axis placements."""
from pathlib import Path
from itertools import product
import json,hashlib,argparse
from n100_dart_independent_canonicalization import loops,need
ROOT=Path(__file__).resolve().parents[1]
def perms(core):
 A=core['alpha'];P=core['phi'];n=len(A);S=[P[A[d]] for d in range(n)]
 # Automorphisms are generated by a dart image root; preserve alpha, sigma and outer tag.
 tags=core['core_tags'];out=[d for d,t in enumerate(tags) if t[0]=='outer'];return A,P,S,tags,out
def map_from_root(A,S,tags,root,image):
 n=len(A);M={root:image};stack=[root]
 while stack:
  d=stack.pop()
  for x,y in ((A[d],A[M[d]]),(S[d],S[M[d]])):
   if x in M:need(M[x]==y,'inconsistent automorphism')
   else:M[x]=y;stack.append(x)
 return M

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--out',default='verify/out/n100-axis-automorphism-orbits.json');args=ap.parse_args();load=lambda p:json.loads(p.read_text(encoding='utf-8'))
 cp=ROOT/'verify/out/n100-cubic-core-roundtrip.json';pp=ROOT/'verify/out/n100-axis-subdivision-pruning.json';core=load(cp)['core'];prior=load(pp);A,P,S,tags,out=perms(core);n=len(A);autos=[]
 for image in range(n):
  if tags[image][0]!=tags[out[0]][0]:continue
  try:M=map_from_root(A,S,tags,out[0],image)
  except ValueError:continue
  if len(M)!=n and False:continue
  if all(tags[d]==tags[M[d]] for d in range(n)) and all(M[A[d]]==A[M[d]] and M[S[d]]==S[M[d]] for d in range(n)):
   autos.append([M[d] for d in range(n)])
 need(autos,'no automorphisms');need(all(len(set(M))==n for M in autos),'bijections')
 fc=loops(P);outer_face=next(row for row in fc if tags[row[0]][0]=='outer');boundary=[A[d] for d in reversed(outer_face)];pos={d:i for i,d in enumerate(boundary)};actions=[]
 for M in autos:
  image=[pos[M[d]] for d in boundary];need(all(x is not None for x in image),'boundary invariant');actions.append(image)
 # placements are four labeled axis positions; automorphism only acts if it preserves cyclic orientation of axis slots, then quotient by action.
 placements=[tuple(x) for x in prior['retained_axis_edge_placements']];Pset=set(placements);orbits=[];seen=set()
 for p in placements:
  if p in seen:continue
  orb={tuple(image[p[i]] for i in range(4)) for image in actions};need(orb<=Pset,'action leaves placements');seen|=orb;orbits.append({'representative':list(min(orb)),'members':sorted(map(list,orb))})
 need(sum(len(o['members']) for o in orbits)==len(placements),'orbit partition');need(tuple(load(ROOT/'verify/out/n100-axis-subdivision-pruning.json')['candidate_axis_edge_indices']) in seen,'candidate seen')
 outp=ROOT/args.out;need(not outp.exists(),'overwrite');outp.write_text(json.dumps({'schema':'n100-axis-automorphism-orbits/v1','verified':True,'dart_count':n,'automorphism_count':len(autos),'automorphism_dart_maps':autos,'boundary_actions':actions,'input_placements':len(placements),'orbit_count':len(orbits),'orbit_size_histogram':{str(k):sum(len(o['members'])==k for o in orbits) for k in sorted(set(map(lambda o:len(o['members']),orbits)))},'orbits':orbits,'candidate_in_partition':True,'scope':'exact automorphisms of one fixed core acting on labeled four-axis boundary placements; no full core enumeration','global_optimality':False,'machine_verified_geometry':False,'bindings':{str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in (cp,pp)},'script_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest()},indent=2)+'\n',encoding='utf-8');print('PASS core autos',len(autos),'placements',len(placements),'orbits',len(orbits))
if __name__=='__main__':main()
